    /// <summary>A fan unfolds from the bottom, the fan axis at the top edge's midpoint,</summary>
    FanT = 231,

    /// <summary>A fan unfolds from the left, the fan axis at the right edge's midpoint,</summary>
    FanR = 232,

    /// <summary>A fan unfolds from the top, the fan axis at the bottom edge's midpoint,</summary>
    FanB = 233,

    /// <summary>A fan unfolds from the right, the fan axis at the left edge's midpoint,</summary>
    FanL = 234,

    /// <summary>Two fans, their axes at the top and bottom, unfold from the center,</summary>
    DoublefanFiv = 235,

    /// <summary>Two fans, their axes at the left and right, unfold from the center,</summary>
    DoublefanFih = 236,

    /// <summary>A radial hand sweeps clockwise from the upper-left corner,</summary>
    SinglesweepCwtl = 241,

    /// <summary>A radial hand sweeps counter-clockwise from the lower-left corner.,</summary>
    SinglesweepCwbl = 242,

    /// <summary>A radial hand sweeps clockwise from the lower-right corner,</summary>
    SinglesweepCwbr = 243,

    /// <summary>A radial hand sweeps counter-clockwise from the upper-right corner,</summary>
    SinglesweepCwtr = 244,

    /// <summary>Two radial hands attached at the upper-left and lower-right corners sweep down and up,</summary>
    DoublesweepPdtl = 245,

    /// <summary>Two radial hands attached at the lower-left and upper-right corners sweep down and up,</summary>
    DoublesweepPdbl = 246,

    /// <summary>Two radial hands attached at the upper-left and upper-right corners sweep down,</summary>
    SaloondoorT = 251,

    /// <summary>Two radial hands attached at the upper-left and lower-left corners sweep to the right,</summary>
    SaloondoorL = 252,

    /// <summary>Two radial hands attached at the lower-left and lower-right corners sweep up,</summary>
    SaloondoorB = 253,

    /// <summary>Two radial hands attached at the upper-right and lower-right corners sweep to the left,</summary>
    SaloondoorR = 254,

    /// <summary>
    /// Two radial hands attached at the midpoints of the top and bottom halves sweep from right to left,
    /// </summary>
    WindshieldR = 261,

    /// <summary>
    /// Two radial hands attached at the midpoints of the left and right halves sweep from top to bottom,
    /// </summary>
    WindshieldU = 262,

    /// <summary>
    /// Two sets of radial hands attached at the midpoints of the top and bottom halves sweep from top to bottom and bottom to top,
    /// </summary>
    WindshieldV = 263,

    /// <summary>
