    /// </summary>
    WindshieldH = 264,

    /// <summary>Crossfade</summary>
    Crossfade = 512,

    /// <summary>
    /// Similar to crossfade, but fade in the front video without fading out
    /// the background one
    /// </summary>
    FadeIn = 513,
}

